using System.Collections;
using System.Collections.Generic;
using BrakeToy.Core;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using PlayMode=BrakeToy.Core.PlayMode;
namespace BrakeToy.Tests
{
    public sealed class PlaygroundSceneTests
    {
        private GameManager game;private PlaygroundRun run;
        private IEnumerator Load(){yield return SceneManager.LoadSceneAsync("ToyRoomPlayground");yield return null;game=Object.FindFirstObjectByType<GameManager>();game.enabled=false;game.Review.Persist=false;game.Arcade.PersistRecords=false;run=game.GetComponent<PlaygroundRun>();run.PersistPreferences=false;game.GetComponent<ToyAudioSettings>().PersistPreferences=false;game.GetComponent<GraphicsProfileController>().PersistPreferences=false;}
        private void Clear(){foreach(var h in game.Arcade.Pool)h.Release();foreach(var r in game.GetComponent<JoyfulRun>().Ramps)r.Release();game.GetComponent<PlaygroundEncounters>().ResetRun();}
        [UnityTest]public IEnumerator RampsLiftBothEdgesInAllLanesAndLandWithoutPassingThrough()
        {yield return Load();var jump=game.GetComponent<JoyfulRun>();foreach(float lane in new[]{-1.8f,0,1.8f})foreach(float edge in new[]{-.8f,0,.8f}){game.StartRun();Clear();float x=lane+edge;jump.SpawnRamp(lane,3);bool climbed=false,flew=false;for(int i=0;i<155;i++){game.Arcade.Step(1f/60,x,x);if(jump.Height>.1f)climbed=true;if(jump.Airborne)flew=true;if(i<18){foreach(var r in jump.Ramps)if(r.InUse&&!r.Launched)Assert.That(jump.Height,Is.GreaterThanOrEqualTo(PlaygroundRules.RampSurface(x-lane,-r.transform.position.z,game.Config.PlayerHalfWidth,game.Config.PlayerHalfLength)-.01f));}}Assert.That(climbed&&flew,Is.True,"lane="+lane+" edge="+edge);Assert.That(jump.Jumps,Is.EqualTo(1));Assert.That(jump.Height,Is.EqualTo(0).Within(.02f));}}
        [UnityTest]public IEnumerator PowersHaveRealDurationFreezeOnPauseAndDoNotRefillOnRetry()
        {yield return Load();game.Review.Data.slowCharges=game.Review.Data.rocketCharges=game.Review.Data.jetCharges=3;foreach(ToyPower p in new[]{ToyPower.Slow,ToyPower.Rocket,ToyPower.Jetpack}){game.StartRun();Clear();Assert.That(run.Activate(p),Is.True);Assert.That(run.Activate(ToyPower.Slow),Is.False);float remaining=run.Remaining;game.Pause();for(int i=0;i<60;i++)game.Arcade.Step(1f/60,0,0);Assert.That(run.Remaining,Is.EqualTo(remaining));game.Resume();float duration=PlaygroundRules.Duration(p);for(int i=0;i<(int)(duration*60)+2;i++){Clear();game.Arcade.Step(1f/60,0,0);}Assert.That(run.ActivePower.HasValue,Is.False);Assert.That(PlaygroundRules.Charges(game.Review.Data,p),Is.EqualTo(2));game.StartRun();Assert.That(PlaygroundRules.Charges(game.Review.Data,p),Is.EqualTo(2));}}
        [UnityTest]public IEnumerator SlowPreservesSteeringAndRocketMovesFurtherWhileJetLifts()
        {yield return Load();var distances=new float[3];for(int k=0;k<3;k++){game.StartRun();Clear();game.Review.Data.slowCharges=game.Review.Data.rocketCharges=game.Review.Data.jetCharges=3;run.Activate((ToyPower)k);for(int i=0;i<60;i++){Clear();game.Arcade.Step(1f/60,0,0);}distances[k]=game.Arcade.Distance;if(k==2)Assert.That(game.GetComponent<JoyfulRun>().Height,Is.GreaterThan(2));}Assert.That(distances[1],Is.GreaterThan(distances[2]*1.7f));Assert.That(distances[0],Is.LessThan(distances[2]*.4f));}
        [UnityTest]public IEnumerator EveryAuthoredFamilyHasAReachableSafeRouteAndNoPoolExhaustion()
        {yield return Load();game.Arcade.VaryRuns=false;foreach(var mode in new[]{PlayMode.Arcade,PlayMode.Relax})foreach(int seed in new[]{7331,109,917}){game.Review.Mode=mode;game.Arcade.Seed=seed;game.StartRun();var seq=new PlaygroundSequence(seed,mode==PlayMode.Relax);var rows=new List<PlaygroundBeat>();for(int i=0;i<150;i++)rows.Add(seq.Next());int row=0;float x=0;for(int i=0;i<7200;i++){while(row<rows.Count-1&&rows[row].Distance+30<game.Arcade.Distance)row++;float next=Mathf.MoveTowards(x,rows[row].SafeX,game.Config.MaxLateralSpeed/60);game.Arcade.Step(1f/60,x,next);x=next;Assert.That(game.State,Is.EqualTo(RunState.Running),"seed="+seed+" t="+game.Arcade.Elapsed+" row="+row); }Assert.That(game.Arcade.PoolExhaustions,Is.Zero);Assert.That(game.Review.Lives,Is.EqualTo(mode==PlayMode.Relax?3:1));}}
        [UnityTest]public IEnumerator ReversibleFeaturesAndVisualMissionCardsArePresent()
        {yield return Load();var atmosphere=game.GetComponent<PlaygroundAtmosphere>();bool before=run.TableZones;run.ToggleZones();Assert.That(run.TableZones,Is.Not.EqualTo(before));run.ToggleZones();Assert.That(run.TableZones,Is.EqualTo(before));var safe=game.UI.SafeArea;Assert.That(safe.Find("Görevler/Mission card 0"),Is.Not.Null);Assert.That(safe.Find("Ana menü").GetComponent<RectTransform>().anchorMax.y,Is.LessThan(.55f));Assert.That(run.PowerRig,Is.Not.Null);foreach(var z in atmosphere.Zones)Assert.That(z.GetComponentsInChildren<Collider>(true).Length,Is.Zero);}
        [UnityTest]public IEnumerator DominoContactTopplesSequenceAndOpensBarrierBeforeCleanup()
        {yield return Load();game.StartRun();Clear();run.DominoEnabled=true;var e=game.GetComponent<PlaygroundEncounters>();int slot=0;e.Spawn(new PlaygroundBeat(0,0,1,4,0,0),6,(kind,x,z,cross,slope)=>{var h=game.Arcade.Pool[slot++];h.HalfWidth=.6f;h.Place(x,z,cross,slope);return h;});PlaygroundProp prop=null;foreach(var p in e.Props)if(p.InUse)prop=p;Assert.That(prop,Is.Not.Null);for(int i=0;i<21;i++)e.Advance(.05f,1,0,0);Assert.That(prop.Triggered,Is.True);Assert.That(prop.Barrier.InUse,Is.False);Assert.That(prop.Dominoes[6].localEulerAngles.x,Is.GreaterThan(40));Assert.That(game.Arcade.Style.Total,Is.GreaterThanOrEqualTo(120));run.ToggleDomino();Assert.That(prop.InUse,Is.False);}
        [UnityTest]public IEnumerator GateSignalFollowsOpenStateAndSafeBypassSurvivesFullCycle()
        {yield return Load();game.StartRun();Clear();var e=game.GetComponent<PlaygroundEncounters>();int slot=0;e.Spawn(new PlaygroundBeat(0,0,1,2,0,0),100,(kind,x,z,cross,slope)=>{var h=game.Arcade.Pool[slot++];h.Place(x,z,cross,slope);return h;});PlaygroundProp prop=null;foreach(var p in e.Props)if(p.InUse)prop=p;bool open=false,closed=false;for(int i=0;i<190;i++){game.Arcade.Step(1f/60,-2.55f,-2.55f);bool now=e.IsOpen(prop.Barrier);open|=now;closed|=!now;Assert.That(prop.Gate.localPosition.y>2.16f,Is.EqualTo(now));Assert.That(game.State,Is.EqualTo(RunState.Running));}Assert.That(open&&closed,Is.True);}
        [UnityTest]public IEnumerator RocketClearsContactAndJetpackEndsAtGroundWithLandingGrace()
        {yield return Load();game.StartRun();Clear();game.Review.Data.rocketCharges=1;Assert.That(run.Activate(ToyPower.Rocket),Is.True);var h=game.Arcade.Pool[0];h.Place(0,2,0,0);game.Arcade.Step(.1f,0,0);Assert.That(h.InUse,Is.False);Assert.That(game.State,Is.EqualTo(RunState.Running));game.StartRun();Clear();game.Review.Data.jetCharges=1;run.Activate(ToyPower.Jetpack);for(int i=0;i<301;i++){Clear();game.Arcade.Step(1f/60,0,0);}Assert.That(game.GetComponent<JoyfulRun>().Height,Is.LessThan(.01f));Assert.That(run.Protected,Is.True);}
        [UnityTest]public IEnumerator DiagonalSideEntryAndExitDoNotDropCarThroughBookSurface()
        {yield return Load();game.StartRun();Clear();var jump=game.GetComponent<JoyfulRun>();jump.SpawnRamp(0,1.5f);game.Arcade.Step(.05f,1.6f,.75f);Assert.That(jump.Height,Is.GreaterThan(.2f));float before=jump.Height;game.Arcade.Step(1f/60,.75f,1.5f);Assert.That(jump.Height,Is.GreaterThan(before*.75f));Assert.That(jump.Airborne,Is.True);}

        [UnityTest]public IEnumerator OptionalRoutesSpawnCollectibleRewardsIncludingAirborneStars()
        {yield return Load();game.StartRun();Clear();Assert.That(game.Arcade.Challenges.RiskStars.Length,Is.GreaterThanOrEqualTo(24));var c=game.Arcade.Challenges;c.ResetRun();c.SpawnAt(0,2);c.Step(3,0,0,false);Assert.That(c.Goals.Pickups,Is.EqualTo(1));game.Review.Data.jetCharges=1;run.Activate(ToyPower.Jetpack);for(int i=0;i<40;i++){Clear();game.Arcade.Step(1f/60,0,0);}foreach(var star in c.RiskStars)star.gameObject.SetActive(false);int before=c.Goals.Pickups;c.SpawnAt(0,2,2);c.Step(3,0,0,false);Assert.That(c.Goals.Pickups,Is.EqualTo(before+1));}

        [UnityTest]public IEnumerator EndingAnAssistedRunRemovesAttachmentsAndLiftWithoutRefundingCharge()
        {yield return Load();game.StartRun();Clear();game.Review.Data.jetCharges=3;run.Activate(ToyPower.Jetpack);for(int i=0;i<30;i++){Clear();game.Arcade.Step(1f/60,0,0);}Assert.That(game.GetComponent<JoyfulRun>().Height,Is.GreaterThan(1));game.Pause();game.Crash();yield return null;Assert.That(run.ActivePower.HasValue,Is.False);Assert.That(game.GetComponent<JoyfulRun>().Height,Is.Zero);Assert.That(run.JetRig.gameObject.activeSelf,Is.False);Assert.That(game.Review.Data.jetCharges,Is.EqualTo(2));Assert.That(run.Assisted,Is.True);}

    }
}
